package ui

import (
	"bytes"
	"html/template"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/ivantit66/onebase/internal/metadata"
	"github.com/ivantit66/onebase/internal/processor"
)

func helpChapterURL(id string) string { return "/ui/help/chapter/" + url.PathEscape(id) }

func (s *Server) addHelpContext(r *http.Request, data map[string]any) {
	b := s.reg.Help()
	data["HasHelp"] = b.Available()
	if !b.Available() {
		return
	}
	// Work for both managed and autogenerated forms, including lists, reports,
	// processors and pages. URLs use the same kind/name convention as bindings.
	parts := strings.Split(strings.Trim(r.URL.Path, "/"), "/")
	if len(parts) < 3 || parts[0] != "ui" {
		return
	}
	kind, name := parts[1], parts[2]
	if proc, ok := data["Processor"].(*processor.Processor); ok && proc != nil {
		// Managed processors also expose a virtual catalog Entity for their
		// parameters; help bindings must keep the actual processor identity.
		kind, name = "processor", proc.Name
	} else if ent, ok := data["Entity"].(*metadata.Entity); ok {
		kind, name = string(ent.Kind), ent.Name
	}
	form := ""
	if f, ok := data["Form"].(*metadata.FormModule); ok {
		form = f.Name
	}
	if c := b.Context(kind+"/"+name, form); c != nil {
		data["HelpURL"] = helpChapterURL(c.ID)
	}
}

func (s *Server) helpIndex(w http.ResponseWriter, r *http.Request) {
	b := s.reg.Help()
	if !b.Available() {
		http.NotFound(w, r)
		return
	}
	query := r.URL.Query().Get("q")
	s.render(w, r, "page-help", map[string]any{"HelpBook": b, "HelpChapters": b.Search(query), "HelpQuery": query})
}

func (s *Server) helpChapter(w http.ResponseWriter, r *http.Request) {
	b := s.reg.Help()
	if !b.Available() {
		http.NotFound(w, r)
		return
	}
	c := b.Find(chi.URLParam(r, "chapter"))
	if c == nil {
		http.NotFound(w, r)
		return
	}
	body, err := b.Render(c, helpChapterURL, func(p string) string { return "/ui/help/assets/" + (&url.URL{Path: p}).EscapedPath() })
	if err != nil {
		s.serverError(w, r, err)
		return
	}
	s.render(w, r, "page-help", map[string]any{
		"HelpBook": b, "HelpChapters": b.Search(""), "HelpChapter": c,
		"HelpBody": template.HTML(body), //nolint:gosec // G203: Goldmark disables raw HTML and unsafe URL schemes; local links are rewritten by Book.Render.
	})
}

func (s *Server) helpAsset(w http.ResponseWriter, r *http.Request) {
	b := s.reg.Help()
	if !b.Available() {
		http.NotFound(w, r)
		return
	}
	name := chi.URLParam(r, "*")
	// chi uses RawPath when present; otherwise the wildcard comes from the
	// already decoded Path and literal percent sequences must stay unchanged.
	if r.URL.RawPath != "" {
		if decoded, err := url.PathUnescape(name); err == nil {
			name = decoded
		}
	}
	a, ok := b.Assets[name]
	if !ok {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Content-Type", a.MIME)
	w.Header().Set("X-Content-Type-Options", "nosniff")
	http.ServeContent(w, r, name, time.Time{}, bytes.NewReader(a.Data))
}

